import type { Caption } from "@remotion/captions";

// Edit timelines generated by student-interviews/edit/build.py.

export type StudentInfo = {
  // Approximate face centre in the 1080×1920 proxy.
  face: number[];
  file: string;
  name: string;
  age: string;
  from: string;
  uni: string;
  program: string;
  city: string;
};

export type Segment = {
  src: string;
  // Source range in seconds.
  from: number;
  to: number;
  // Position on the output timeline in seconds.
  at: number;
  student: string;
  item: number;
  cut: "start" | "jump" | "switch";
  // Source time before which the audio stays muted (a held question beat).
  muteUntil?: number;
};

export type Item =
  | {
      kind: "clip";
      student: string;
      start: number;
      end: number;
      hook?: boolean;
      passport?: boolean;
      bubble?: string;
      bubbleLead?: number;
      truth?: string;
    }
  | {
      kind: "title" | "myth" | "end";
      text: string;
      start: number;
      end: number;
    };

export type VoicesData = {
  id: string;
  format: "story" | "question" | "myths";
  title: string;
  question: string | null;
  durationSec: number;
  durationInFrames: number;
  students: Record<string, StudentInfo>;
  order: string[];
  segments: Segment[];
  items: Item[];
  captions: (Caption & { pageBreakAfter?: boolean })[];
};
